<?php
namespace Semizzy\Addons\BulkSms\Models; use Illuminate\Database\Eloquent\Model; class BulkSmsCampaign extends Model {protected $table='bulk_sms_campaigns';protected $guarded=[];protected $casts=['scheduled_at'=>'datetime','edit_until'=>'datetime','started_at'=>'datetime','completed_at'=>'datetime'];public function product(){return $this->belongsTo(BulkSmsProduct::class,'product_id');}public function messages(){return $this->hasMany(BulkSmsMessage::class,'campaign_id');}}